/* Student experience, local persistence and separate print views. */
(function(){
'use strict';
const C=window.RTCore,A=window.RTArt,$=x=>document.querySelector(x),h=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let storage;try{storage=window.localStorage}catch{}const store=new C.Store(storage);
let s=null,errors=[],notice='',saveText='Choose or start a session',saveError='',teacher=false,learner='A',plotPoint=1,modalReturn=null,pendingImport=null,pendingDelete=[],pendingReplace=false,conflict=false;
const money=v=>{try{return '$'+C.q(v).fixed(2)}catch{return '$'+C.numeric(v).fixed(2)}},txt=k=>s?.inputs[k]||'',value=k=>h(txt(k)||'—');
function rational(v){try{const a=v instanceof C.Q?v:C.numeric(String(v));if(a.d===1n)return h(a.str());return `${a.n<0n?'−':''}<span class="frac" role="math" aria-label="${h(a.str())}"><span>${a.n<0n?-a.n:a.n}</span><span>${a.d}</span></span>`}catch{return h(v||'—')}}
const opts={classOne:[['once','Once for this route'],['day','Every day'],['night','Every night']],slopeMeaning:[['daily','Cost of one additional day (USD/day)'],['total','Cost of the seven-day trip'],['fixed','Fuel and one-off expenses']],constantMeaning:[['adjusted','One-off + fuel − one night of hotel (USD)'],['dayZero','Money literally spent on a zero-day trip'],['hotel','Only the hotel cost']],domain:[['whole','Whole days from 1 through 14'],['any','Any nonnegative decimal'],['seven','Only seven days']],xAxis:[['days','Days'],['cost','Cost (USD)']],yAxis:[['cost','Cost (USD)'],['days','Days']],yStep:['50','100','200','500','1000'],budgetShape:[['horizontal','Horizontal'],['sloped','Sloped with the trip-cost line'],['vertical','Vertical']],maxDays:[...Array.from({length:14},(_,i)=>String(i+1)),['none','No affordable trip']],lodgingPriority:[['yes','Yes'],['no','No']],activityPriority:[['yes','Yes'],['no','No']],recommendation:[['recommend','Recommend this plan'],['revise','Recommend a revision']],evidenceType:[['total','Trip total'],['reserve','Budget left'],['percent','Percent spent']],deltaReason:[['nights','The added term is 20(d − 1): six nights in seven days'],['days','The added term is 20d: seven nights in seven days'],['once','The increase is a single $20 charge']]};
for(const k of Object.keys(C.CLASS))opts[k]=opts.classOne;
const calculator=new Set(['liters','fuelCost','partyFood','table1','table3','table5','table7','costAtMax','nextDayCost','total','reserve','percent','deltaSlope','deltaConstant','deltaTotal','transferTotalA','transferTotalB']);
const statusName={unstarted:'Not checked',inProgress:'Try again',verified:'Checked',needsRecheck:'Needs recheck',overridden:'Teacher bypass — provisional',notRequired:'Not required'};
const helpText={
 C01:['A cost may happen once for the route, every day, or every night.','Choose one frequency for each cost. Food is priced per person per day.','Ask what changes when only the number of days changes.','$25 booking is once; $12/day rental is daily.'],
 C02:['km/L means kilometers traveled using one liter of fuel.','Liters: exact number or fraction. Fuel: USD rounded to cents.','Divide total km by km/L, then multiply liters by price/L. Keep exact fractions until the fuel subtotal.','240 km ÷ 12 km/L = 20 L. At $1.50/L, fuel is $30.'],
 C03:['Per-person food covers every traveler. Nights are one fewer than travel days.','Food: USD/group/day. Nights: whole number. Hotel: a rule using d.','Multiply food price by people; multiply hotel price by (d − 1).','Four people at $8 cost $32/day. Five days have four nights; a $50 hotel gives 50(d − 1).'],
 C04:['A model combines every cost. m is daily change; b is the constant after simplifying.','Use d for days, numbers, +, −, ×, ÷ and parentheses. Enter m and b independently.','Write each of the six cost terms. Expand the nightly term, then collect daily and constant parts.','50d + 70(d − 1) + 100 = 120d + 30. Here m = 120 USD/day and b = 30 USD.'],
 C05:['A point is (days, cost). Equal axis distances represent equal changes.','Table: USD. Horizontal axis: days; vertical axis: USD. Points accept exact cents.','Use your checked rule for each day. Plot each pair and draw a horizontal budget line. You can type every coordinate.','For C(d) = 100d + 50, three days gives (3, 350). A $600 budget lies at y = 600.'],
 C06:['The budget crossing may fall between whole-day trips.','Use ≤ or >= correctly. Enter an exact fraction or (budget − constant)/daily rate for the bound.','Set cost ≤ budget, solve for d, then check the last affordable whole day and the next day.','100d + 50 ≤ 600 gives d ≤ 5.5. Five days fit; six cost $650 and do not.'],
 C07:['Reserve is signed money left. Percent compares spending with the whole budget.','Money: USD. Percent: round half up to 0.01%. A short reason stays pending teacher review.','Subtract cost from budget. Divide cost by budget and multiply by 100. Explain one checked number.','$1,000 − $850 = $150; 850/1000 × 100 = 85%. A $1,050 cost gives −$50 reserve.'],
 C08:['A nightly increase changes both parts of a days-based rule.','Coefficient change: USD/day. Constant and total changes: USD; include a minus sign when needed.','Add the new nightly amount times (d − 1), then expand. Compare with the frozen original plan before changing choices.','A $10 rise over four nights adds $40. +10(d − 1) changes m by +10 and b by −10.'],
 C09:['A new trip has a daily part and a once-only part.','Use d in the rule. Enter the requested trip total in USD.','Work independently. Write daily rate × days + once-only cost, then substitute the requested days.','$90/day plus $120 once gives T(d) = 90d + 120. Three days cost $390.']};
function save(){if(!s)return;if(conflict){saveText='Conflict — choose reload or copy';return}try{store.save(s);saveText='Saved on this device';saveError=''}catch(e){saveText='Not saved on this device';if(e.message==='CONFLICT'){conflict=true;saveError='A newer copy exists in another tab. Reload it or save your current work as a new copy.'}else saveError=e.message}updateSave()}
function updateSave(){const el=$('#save-label');if(el)el.textContent=saveText;const warn=$('#storage-notice');if(warn){warn.hidden=!saveError;warn.innerHTML=h(saveError)+(conflict?' <button data-action="reload-conflict">Reload saved copy</button> <button data-action="copy-conflict">Save as new copy</button>':' <button data-action="export">Export current progress</button>')}}
function top(){return `<header class="topbar"><div class="brand">Road Trip Planner<span>A WILLIAM MCADA PRODUCT</span></div><div class="toolbar"><span id="save-label" class="save-label" role="status">${h(saveText)}</span>${s?'<button class="quiet" data-action="save">Save</button><button class="quiet" data-action="export">Export progress</button>':''}<button class="quiet" data-action="sessions">Saved work</button><button class="quiet" data-action="teacher">Teacher${teacher?' • on':''}</button></div></header>`}
function footer(){return '<footer class="footer"><span>William McAda · Applied Math Projects</span><span>App 0.1.0 · Content 1.0.0 · Runs offline · No accounts or tracking</span></footer>'}
function render(focus=false){const y=window.scrollY;$('#app').innerHTML=top()+`<div class="wrap"><div id="storage-notice" class="notice warning" role="status" ${saveError?'':'hidden'}></div>${s?workspace():home()}</div>`+footer();updateSave();if(focus){$('#main')?.focus();window.scrollTo(0,0)}else window.scrollTo(0,y)}
function home(){return `<main id="main" tabindex="-1"><section class="hero"><div><p class="eyebrow">Applied mathematics / Project 01</p><h1>A great trip starts<br>with a good plan.</h1><p class="lead">Three travelers. Seven days. One budget.<br>Build a road trip your clients will love—and show why the numbers work.</p><div class="facts"><div><strong>$1,800</strong><small>total budget</small></div><div><strong>900 km</strong><small>return route</small></div><div><strong>3 lessons</strong><small>about 45 minutes each</small></div></div><div class="actions"><button data-action="new">Start a new journey →</button><button class="secondary" data-action="sessions">Resume saved work</button></div></div><div class="hero-art">${A.hero()}</div></section><div class="source-grid"><div class="source-card"><strong>Plan together</strong><span>Work as Planner and Checker. Swap roles after each lesson.</span></div><div class="source-card"><strong>Make the case</strong><span>Build a rule, table, graph and budget recommendation.</span></div><div class="source-card"><strong>Expect a change</strong><span>Revise a quote, then try a short task on your own.</span></div></div><p class="caption" style="margin-top:30px">Use aliases instead of names. Saved work stays in this browser. Export a JSON progress file before changing devices or clearing browser data.</p></main>`}
function workspace(){let stage=s.currentStage;return `<nav class="progress" aria-label="Journey stages">${C.stages.map((label,i)=>`<button data-stage="${i+1}" class="${stage===i+1?'active':i<s.maxStage?'visited':''}" ${stage===i+1?'aria-current="step"':''}><strong>${String(i+1).padStart(2,'0')}</strong>${label}</button>`).join('')}</nav>${notice?`<div class="notice" role="status">${h(notice)}</div>`:''}<div class="workspace"><main id="main" class="main" tabindex="-1"><p class="eyebrow">Stage ${stage} of 8 · ${h(s.teamAlias||'Your team')}</p><h1>${h(C.stages[stage-1])}</h1>${errors.length?`<div class="error-summary" id="error-summary" tabindex="-1" role="alert"><strong>Check these fields</strong>${errors.map(e=>`<p><a href="#f-${h(e.key)}" data-error-link="${h(e.key)}">${h(e.message)}</a></p>`).join('')}</div>`:''}${stageContent(stage)}<div class="actions">${stage>1?'<button class="secondary" data-action="back">← Back</button>':''}${stage<8?`<button data-action="next">${stage===7?'Continue to client presentation':'Check & continue'} →</button>`:'<button data-action="finish">Check transfer & reveal outcome</button>'}<button class="quiet" data-action="proposal">Preview / print proposal</button></div></main>${sidebar()}</div>`}
function sidebar(){let m;try{m=C.scenario(s)}catch{return '<aside class="sidebar"><p>Finish the route details to update your itinerary.</p></aside>'}return `<aside class="sidebar" aria-label="Itinerary summary"><div>${A.scene('vehicle',txt('vehicle'))}<p class="caption">A schematic journey, not a live map.</p></div><div><p class="eyebrow">Your itinerary</p><div class="role-pill">Planner ${h(txt('planner'))} · Checker ${txt('planner')==='A'?'B':'A'}</div><dl>${Object.entries(m.selected).map(([k,v])=>`<dt>${h(k==='hotel'?'Lodging':k)}</dt><dd>${h(v[1])}</dd>`).join('')}</dl><div class="sum"><small>Client fit</small><br><strong>${m.U} / 100</strong> <small>preference rating</small></div><div class="sum"><small>Trip total</small><br><strong>${C.state(s,'total')==='verified'?money(m.total):'Calculate in Budget review'}</strong></div><p class="caption">${s.eventApplied?'Updated hotel prices are active.':'Original hotel quote is active.'} Client fit describes the design, not your math grade.</p><button class="quiet" data-action="ratings">View client priorities</button></div></aside>`}
function field(key){const d=C.definitions(s)[key];if(!d||d.kind==='notRequired')return '';let state=C.state(s,key),err=errors.find(e=>e.key===key),options=opts[key],control;const attr=`id="f-${key}" data-field="${key}" aria-describedby="hint-${key} status-${key}" ${err?'aria-invalid="true"':''}`;if(options){control=`<select ${attr}><option value="">Choose…</option>${options.map(o=>{let [v,label]=Array.isArray(o)?o:[o,o];return `<option value="${h(v)}" ${txt(key)===v?'selected':''}>${h(label)}</option>`}).join('')}</select>`}else if(d.kind==='text'){control=`<textarea ${attr} maxlength="280">${h(txt(key))}</textarea>`}else{control=`<input ${attr} type="text" inputmode="text" autocomplete="off" spellcheck="false" maxlength="256" value="${h(txt(key))}">`}return `<label class="field ${d.kind==='text'||['expression','hotelExpression','inequality','slopeMeaning','constantMeaning','domain','deltaReason'].includes(key)?'wide':''}" for="f-${key}"><span class="field-label">${h(d.label)}${d.unit?`<span class="unit">${h(d.unit)}</span>`:''}</span>${control}<span class="hint" id="hint-${key}">${calculator.has(key)?'Calculator allowed. ':''}${key==='bound'?'Exact fraction or quotient; a rounded decimal is not exact.':key==='fuelCost'?'Round only this fuel subtotal to cents.':key==='percent'?'Round to the nearest 0.01%.':d.kind==='text'?'Received as a response; reasoning quality needs teacher review.':d.kind==='expression'?'Use d for days. Equivalent linear forms are welcome.':''}</span><span id="status-${key}" class="field-state ${state}">${err?h(err.message):statusName[state]}${d.kind==='text'&&C.valid(s,key)?' · Review: '+C.reviewStatus(s,key):''}</span></label>`}
function group(g,keys=C.groups[g],intro=''){return `<section class="panel" aria-label="${h(C.labels[g])}"><div class="checkpoint-id">RT-${g}</div><h3>${C.labels[g]} <button class="help" data-help="${g}" aria-label="Help: ${C.labels[g]}">?</button></h3>${intro?`<p>${intro}</p>`:''}<div class="fields">${keys.map(field).join('')}</div><div class="actions"><button class="secondary" data-check="${g}">Check ${C.labels[g].toLowerCase()}</button></div></section>`}
function setupField(key,label,type='text',extra=''){return `<label class="field" for="f-${key}"><span class="field-label">${label}</span><input id="f-${key}" data-field="${key}" type="${type}" maxlength="${key==='sourceLink'?512:256}" value="${h(txt(key))}" ${extra}></label>`}
function pick(key,label,options){return `<label class="field" for="f-${key}"><span class="field-label">${label}</span><select id="f-${key}" data-field="${key}">${options.map(([v,l])=>`<option value="${h(v)}" ${v===txt(key)?'selected':''}>${h(l)}</option>`).join('')}</select></label>`}
function stageContent(n){switch(n){case 1:return `<p class="lead">Your clients want comfortable lodging and full activities. Plan seven days for three travelers, with a total budget of $1,800.</p><section class="panel"><div class="fields"><label class="field" for="team-alias"><span class="field-label">Team alias</span><input id="team-alias" maxlength="64" value="${h(s.teamAlias)}" autocomplete="off" placeholder="For example: Team Cedar"></label>${pick('planner','Who plans first?',[['A','Learner A — Planner'],['B','Learner B — Planner']])}${pick('briefPriority1','First client priority',[['','Choose…'],['lodging','Comfortable lodging'],['vehicle','The most expensive vehicle'],['food','The largest food budget']])}${pick('briefPriority2','Second client priority',[['','Choose…'],['activities','Full activities'],['vehicle','The largest vehicle'],['distance','The longest route']])}</div></section><p>The <strong>Planner</strong> enters the plan and explains each step. The <strong>Checker</strong> checks units, calculations and reasoning. Swap after lessons one and two.</p>${ratings()}<p class="caption">Client fit is a disclosed preference score. Correct mathematics can describe an unaffordable or less suitable trip; you will still be able to explain and revise it.</p>`;
case 2:return routeScreen();case 3:return choiceScreen()+group('C01',undefined,'Sort each cost by when it happens.')+group('C02',undefined,`The fixed route uses a vehicle rated at <strong>12 km/L</strong>. Fuel costs <strong>$1.60/L</strong>. The route distance is <strong>${h(txt('routeDistance'))} km</strong>.`)+group('C03')+lesson(1);
case 4:return `<p class="lead">Build a rule for the whole trip. Let <em>d</em> be the number of travel days, from 1 through 14.</p>${costFacts()}<section class="panel">${pick('guided','Rule-building mode',[['no','Type the whole expression'],['yes','Build six labeled terms']])}${txt('guided')==='yes'?`<p>Enter every term yourself. Your six terms will be joined into the full expression when you check.</p><div class="fields">${[['termFixed','One-off expenses'],['termFuel','Fuel for the fixed route'],['termVehicle','Vehicle for d days'],['termHotel','Hotel for d − 1 nights'],['termFood','Food for three people for d days'],['termActivities','Group activities for d days']].map(([k,l])=>setupField(k,l)).join('')}</div>`:''}</section>${group('C04')}`;
case 5:return forecast();case 6:return `<p class="lead">Find the longest trip the budget can cover, then make a recommendation for the requested seven days.</p>${group('C06')}${group('C07')}<p class="caption">A negative reserve or spending over 100% may be mathematically correct. A recommendation sentence is received here and reviewed by your teacher.</p>${lesson(2)}`;
case 7:return eventScreen();case 8:return presentation();}}
function ratings(){return `<section class="panel"><h3>The clients’ preferences</h3><p>At or below budget: <strong>85–100</strong> fit points → delighted; <strong>65–84</strong> → approved. Under 65, or over budget → revision requested.</p><div class="fields">${Object.entries(C.CAT).map(([k,rows])=>`<div><strong>${h(k==='hotel'?'Lodging':k[0].toUpperCase()+k.slice(1))}</strong>${rows.map(v=>`<div class="caption">${h(v[1])}: ${v[3]} points</div>`).join('')}</div>`).join('')}</div></section>`}
function routeScreen(){const research=txt('routeMode')==='researched';return `<p class="lead">One fixed return route. A longer stay changes the daily costs, but it does not make the route longer.</p><div class="route-art">${A.route()}</div><p class="caption">Schematic classroom route · not to scale</p><div class="source-grid"><div class="source-card"><strong>900 km</strong><span>Provided total return distance</span></div><div class="source-card"><strong>12 km/L</strong><span>Vehicle fuel efficiency</span></div><div class="source-card"><strong>$1.60/L</strong><span>Fuel price</span></div></div><section class="panel"><h3>Route source <button class="help" data-help="route" aria-label="Help: route source">?</button></h3>${pick('routeMode','Choose your source',[['provided','Use the provided classroom route'],['researched','Enter a researched route with teacher review']])}${research?`<div class="fields" style="margin-top:20px">${setupField('sourceTitle','Source title or provider')}${setupField('sourceLink','Provider or link (optional; inert text)')}${setupField('accessDate','Date accessed','date')}${pick('routeType','What does the source distance describe?',[['roundTrip','The whole return trip'],['oneWay','One way — double for return'],['segmentTotal','Sum of route segments']])}${setupField('originalDistance','Distance recorded from source')}${pick('originalUnit','Source unit',[['km','Kilometers (km)'],['m','Meters (m)']])}${txt('routeType')==='segmentTotal'?setupField('segments','Segments, joined with + (same source unit)'):''}</div><p class="caption">1 km = 1,000 m. Other units need a teacher-recorded conversion first. Format checks cannot verify whether a source is true. Research review: ${h(txt('routeReviewed')==='verified'?'verified':'pending')}.</p>${/^https?:\/\//i.test(txt('sourceLink'))?'<button class="quiet" data-action="open-source">Open source link</button>':''}`:'<p>Source: Harbor City–Lakeview authored classroom route, 900 km total return distance. No map service is required.</p>'}<div style="margin-top:18px">${setupField('routeDistance','Total distance this vehicle will travel (km)')}</div></section>`}
function choiceScreen(){const locked=s.eventApplied&&!s.eventEvidence;return `<p class="lead">Choose the trip, then work out how each cost behaves.</p><p>One-off expenses total <strong>$200</strong>: booking $40, luggage $80 and supplies $80.</p>${locked?'<div class="notice warning">Finish the hotel-change comparison before changing any itinerary choice.</div>':''}${Object.entries(C.CAT).map(([kind,rows])=>`<section style="margin:25px 0"><h3>${h(({vehicle:'Choose your vehicle',hotel:'Choose your lodging',food:'Choose your food plan',activities:'Choose your activities'})[kind])}</h3><div class="cards">${rows.map(row=>{const price=row[2]+(kind==='hotel'&&s.eventApplied?20:0);return `<label class="choice ${txt(kind)===row[0]?'selected':''}">${A.scene(kind,row[0])}<input type="radio" name="${kind}" data-field="${kind}" value="${row[0]}" ${txt(kind)===row[0]?'checked':''} ${locked?'disabled':''}><span class="name">${h(row[1])}</span><span class="price">$${price} / ${kind==='hotel'?'group / night':kind==='food'?'person / day':'group / day'}</span><span class="fit">Client fit: ${row[3]} points${kind==='vehicle'?' · 12 km/L':''}</span></label>`}).join('')}</div></section>`).join('')}`}
function costFacts(){const m=C.scenario(s);return `<div class="panel"><h3>Your quoted rates</h3><p>One-off: $200 · Fuel route: ${h(txt('routeDistance'))} km at 12 km/L and $1.60/L<br>Vehicle: ${money(m.r)}/group/day · Hotel: ${money(m.h)}/group/night<br>Food: ${money(m.f)}/person/day, three travelers · Activities: ${money(m.a)}/group/day</p><p class="caption">A d-day trip has d − 1 nights. The route is unchanged when d changes.</p></div>`}
function lesson(n){return `<div class="lesson"><strong>Lesson ${n} checkpoint</strong><p>Export progress, explain your thinking, then swap Planner and Checker before moving on.</p><div class="actions"><button class="secondary" data-action="export">Export progress</button><button class="quiet" data-action="swap">Swap roles</button></div></div>`}
function graph(interactive=false){const m=C.scenario(s),step=Number(txt('yStep'))||200,upper=Math.ceil(Math.max(m.total.num(),1800)*1.12/step)*step,W=720,H=370,L=62,R=22,T=22,B=53,x=v=>L+v/14*(W-L-R),y=v=>H-B-v/upper*(H-T-B),maj=Math.max(1,Math.ceil(upper/step/12));let body=`<title>Student cost graph: horizontal axis ${h(txt('xAxis')||'unlabeled')}, vertical axis ${h(txt('yAxis')||'unlabeled')}</title><desc>Four exact ordered-pair inputs below provide the accessible data equivalent. Day zero is outside the trip domain.</desc><defs><clipPath id="plot-clip"><rect x="${L}" y="${T}" width="${W-L-R}" height="${H-T-B}"/></clipPath></defs>`;for(let d=0;d<=14;d++)body+=`<path class="grid" d="M${x(d)} ${T}V${H-B}"/><text x="${x(d)}" y="${H-B+20}" text-anchor="middle">${d}</text>`;for(let v=0,i=0;v<=upper;v+=step,i++)body+=`<path class="grid" d="M${L} ${y(v)}H${W-R}"/>${i%maj===0?`<text x="${L-9}" y="${y(v)+4}" text-anchor="end">${v}</text>`:''}`;body+=`<path class="axis" d="M${L} ${T}V${H-B}H${W-R}"/><text x="${W/2}" y="${H-8}" text-anchor="middle">${txt('xAxis')==='days'?'Days':txt('xAxis')==='cost'?'Cost (USD)':'Horizontal axis: choose a label'}</text><text transform="translate(15 ${H/2}) rotate(-90)" text-anchor="middle">${txt('yAxis')==='cost'?'Cost (USD)':txt('yAxis')==='days'?'Days':'Vertical axis: choose a label'}</text><g clip-path="url(#plot-clip)">`;try{let v=C.numeric(txt('budgetLine'),'USD').num();if(Number.isFinite(v)){body+=txt('budgetShape')==='vertical'?`<path d="M${x(v)} ${T}V${H-B}" stroke="#ad503a" stroke-width="2" stroke-dasharray="8 5"/>`:txt('budgetShape')==='sloped'?`<path d="M${x(0)} ${y(0)}L${x(14)} ${y(v)}" stroke="#ad503a" stroke-width="2" stroke-dasharray="8 5"/>`:`<path d="M${L} ${y(v)}H${W-R}" stroke="#ad503a" stroke-width="2" stroke-dasharray="8 5"/>`}}catch{}if(C.groupOK(s,'C05')&&C.groups.C05.every(k=>C.state(s,k)!=='overridden'))body+=`<path d="M${x(1)} ${y(m.cost(1).num())}L${x(14)} ${y(m.cost(14).num())}" fill="none" stroke="#246f6b" stroke-width="2.5"/>`;for(let d of [1,3,5,7])try{const px=C.numeric(txt('x'+d)).num(),py=C.numeric(txt('y'+d),'USD').num();if(Number.isFinite(px)&&Number.isFinite(py))body+=`<circle cx="${x(px)}" cy="${y(py)}" r="6" fill="#246f6b" stroke="#fffef9" stroke-width="2"/>`}catch{}body+='</g>';return `<svg class="graph" viewBox="0 0 ${W} ${H}" role="img" aria-label="Your cost graph" ${interactive?`data-plot="true" data-upper="${upper}"`:''}>${body}</svg>`}
function forecast(){return `<p class="lead">Connect your rule, table, and graph. Enter each point yourself; the checked line appears after your work passes.</p><section class="panel"><div class="checkpoint-id">RT-C05</div><h3>Table and graph <button class="help" data-help="C05" aria-label="Help: table and graph">?</button></h3><div class="table-grid">${[1,3,5,7].map(d=>field('table'+d)).join('')}</div><div class="fields" style="margin:24px 0">${['xAxis','yAxis','yStep'].map(field).join('')}</div>${graph(true)}<p class="caption">One-day horizontal ticks. Day 0 is outside the 1–14 day trip domain. Vertical minor ticks: $${h(txt('yStep'))}; some labels are spaced farther apart for readability.</p><label class="field plot-select">Point to place by tapping<select id="plot-point">${[1,3,5,7].map(d=>`<option value="${d}" ${plotPoint===d?'selected':''}>Point for ${d} days</option>`).join('')}</select></label><p class="caption">Tap to estimate a point, then enter exact coordinates below. Keyboard and touch users can enter every point here without dragging.</p>${[1,3,5,7].map(d=>`<div class="pair-row"><strong>${d} d</strong>${field('x'+d)}${field('y'+d)}</div>`).join('')}<div class="fields" style="margin-top:24px">${['budgetLine','budgetShape','rise'].map(field).join('')}</div><div class="actions"><button class="secondary" data-check="C05">Check table and graph</button></div></section>`}
function eventScreen(){if(!s.eventApplied)return `<div class="ending">${A.alertArt()}<div><p class="lead">An updated hotel quote has arrived.</p><p>Save your original plan, then open the new quote. You will compare both plans before changing other choices.</p><button data-action="apply-event">Open the hotel quote</button></div></div>`;const m=C.scenario(s),b=s.eventBaseline,baseHotel=C.CAT.hotel.find(a=>a[0]===b.inputs.hotel);return `<div class="ending">${A.alertArt()}<div><p class="eyebrow">Updated quote · applied once</p><h3>Every hotel now costs $20 more per night.</h3><p>Your original ${h(baseHotel[1])}: $${baseHotel[2]} → $${baseHotel[2]+20}/night. The same increase applies if you choose another hotel later.</p></div></div>${s.eventEvidence?`<div class="notice">The mandatory comparison is recorded. You can now revise a choice or keep the analyzed plan. Recheck any affected work before presenting.</div><div class="actions"><button class="secondary" data-action="revise">Revise choices</button><button class="quiet" data-action="keep-plan">Keep this analyzed plan</button></div>`:'<div class="notice warning">Keep the original choices while you update the calculations below. Your previous responses are retained; changed quantities need rechecking.</div>'}${group('C08')}<p>Recheck the affected parts of your active plan. The original and event snapshots remain available in your proposal.</p>${['C03','C04','C05','C06','C07'].map(g=>`<details ${!C.groupOK(s,g)?'open':''}><summary>${C.labels[g]} · ${C.groupOK(s,g)?'current':'needs work'}</summary>${g==='C05'?forecast():group(g)}</details>`).join('')}<div class="actions"><button data-action="record-event">${s.eventEvidence?'Recheck active plan':'Record hotel comparison'}</button></div>`}
function presentation(){const result=C.outcome(s),m=C.scenario(s),a=learner,other=a==='A'?'B':'A';return `<p class="lead">Tell the clients what you recommend. Then each learner completes a short, different problem.</p><section class="panel"><h3>Individual transfer <button class="help" data-help="C09" aria-label="Help: individual transfer">?</button></h3><p>Take turns. Learner ${a} works independently while learner ${other} looks away. This classroom activity does not claim to be proctored.</p><div class="tabs">${['A','B'].map(v=>`<button class="secondary" data-learner="${v}" aria-pressed="${v===a}">Learner ${v}</button>`).join('')}</div><p><strong>Learner ${a}:</strong> ${a==='A'?'A different trip costs $160 each day and $240 once. Write T(d). Find the cost for four days.':'Another trip costs $145 each day and $310 once. Write T(d). Find the cost for six days.'}</p>${teacher?pick('transferMode'+a,'Teacher-recorded response mode',[['digital','Digital response'],['paper','Paper submission'],['oral','Oral submission']]):`<p class="caption">Response mode: ${h(txt('transferMode'+a))}. Ask your teacher to record paper or oral work.</p>`}${txt('transferMode'+a)==='digital'?`<div class="fields">${field('transferExpression'+a)+field('transferTotal'+a)}</div><div class="actions"><button class="secondary" data-transfer="${a}">Check learner ${a}</button></div>`:`<p>Submission status: ${s.reviews.some(r=>r.key==='transferMode'+a&&r.response===txt('transferMode'+a))?'recorded; review '+C.reviewStatus(s,'transferMode'+a):'not yet recorded'}. No digital attempts are invented.</p>${teacher?`<button class="secondary" data-record-transfer="${a}">Record learner ${a} submission</button>`:''}`}<div class="actions"><button class="quiet" data-action="slips">Print separate transfer slips</button></div></section><section class="panel"><div class="ending">${A.postcard(result.code)}<div><p class="eyebrow">Client postcard</p><h2>${h(result.title)}</h2><p>${result.code==='draft'?'Finish any missing or stale checks before revealing the client decision.':`${h(m.selected.hotel[1])}, ${h(m.selected.food[1])} and ${h(m.selected.activities[1])}: ${money(m.total)} total, ${money(m.reserve)} left, ${m.U}/100 client fit.`}</p><p class="caption">${reviewSummary()}</p></div></div><div class="actions"><button class="secondary" data-action="revise">Back to revise</button><button class="quiet" data-action="duplicate-active">Duplicate for another revision</button><button class="quiet" data-action="export">Export progress</button></div></section>`}
function reviewSummary(){if(!s)return '';const a=[];for(const k of ['reason','reserveStatement'])if(C.definitions(s)[k].kind!=='notRequired')a.push((k==='reason'?'Recommendation reasoning':'Reserve statement')+': '+C.reviewStatus(s,k));if(txt('routeMode')==='researched')a.push('Research truth: '+(txt('routeReviewed')==='verified'?'verified':'pending'));for(const v of ['A','B'])if(txt('transferMode'+v)!=='digital')a.push('Learner '+v+' '+txt('transferMode'+v)+': '+C.reviewStatus(s,'transferMode'+v));return h(a.join(' · '))}
function capture(){if(!s)return;const alias=$('#team-alias');if(alias)s.teamAlias=alias.value;document.querySelectorAll('[data-field]').forEach(el=>{if(el.type==='radio'&&!el.checked)return;C.setInput(s,el.dataset.field,el.value)});if(txt('guided')==='yes'&&s.currentStage===4){const keys=['termFixed','termFuel','termVehicle','termHotel','termFood','termActivities'];C.setInput(s,'expression',keys.map(k=>'('+txt(k)+')').join(' + '))}}
function showErrors(es){errors=es;save();render();if(es.length){$('#error-summary')?.focus();$('#error-summary')?.scrollIntoView({block:'center'})}}
function checkKeys(keys){capture();const es=C.check(s,keys);showErrors(es);if(!es.length){notice='These checks are current. Your responses and earlier attempts are saved.';render()}return es.length===0}
function next(){capture();notice='';if(s.currentStage===1){let es=[];if(!s.teamAlias.trim())es.push({key:'team-alias',message:'Enter a team alias.'});if(txt('briefPriority1')!=='lodging')es.push({key:'briefPriority1',message:'The clients prioritize comfortable lodging.'});if(txt('briefPriority2')!=='activities')es.push({key:'briefPriority2',message:'The clients also prioritize full activities.'});if(es.length)return showErrors(es)}else if(s.currentStage===2){let es=C.routeErrors(s);if(es.length)return showErrors(es)}else if(s.currentStage===7){if(!s.eventApplied){notice='Open the hotel quote before continuing.';render();return}if(!checkKeys(C.stageKeys(7,s)))return;if(!s.eventEvidence)C.recordEvent(s)}else if(!checkKeys(C.stageKeys(s.currentStage,s)))return;s.currentStage=Math.min(8,s.currentStage+1);s.maxStage=Math.max(s.maxStage,s.currentStage);errors=[];save();render(true)}
function openModal(title,body){modalReturn=document.activeElement;const d=$('#modal');d.innerHTML=`<div class="modal-head"><h2 id="modal-title">${h(title)}</h2><button class="quiet" data-action="close" aria-label="Close dialog">×</button></div>${body}`;if(!d.open)d.showModal();d.scrollTop=0}
function closeModal(){const d=$('#modal');if(d.open)d.close();modalReturn?.isConnected&&modalReturn.focus()}
function showHelp(g){if(s){s.support.push({checkpointId:g==='route'?'route':'RT-'+g,at:C.now(),scenarioRevision:s.scenarioRevision});save()}if(g==='route')return openModal('Route source help','<div class="reading"><h3>Meaning</h3><p>Use the total distance the vehicle travels, including the return journey.</p><h3>Unit and format</h3><p>Enter kilometers or meters; 1 km = 1,000 m. Source links are plain text unless you open them.</p><h3>Procedure</h3><p>Convert units, then double a one-way distance or add all route segments. Record the title and access date. Ask a teacher to review source truth.</p><h3>Different-number example</h3><p>A one-way distance of 120,000 m is 120 km. The return journey totals 240 km.</p></div>');openModal(C.labels[g]+' — help',`<div class="reading">${['Meaning','Unit and format','Procedure','Different-number example'].map((l,i)=>`<h3>${l}</h3><p>${h(helpText[g][i])}</p>`).join('')}</div>`)}
function download(name,data,type='application/json'){const blob=new Blob([typeof data==='string'?data:JSON.stringify(data,null,2)],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000)}
function exportSession(){if(!s)return;capture();save();download('RoadTrip-'+s.sessionId+'.json',s);notice='Progress download requested. Check that the file was saved before leaving this page.';render()}
function bundle(sessions){return {schema:'mcada-project-backup',schemaVersion:'1.0.0',projectId:'road-trip',exportedAt:C.now(),sessions}}
function sessionsModal(){const list=store.list();openModal('Saved work',`<p>Each session includes its answers, attempts, help history, snapshots and teacher reviews.</p><div class="actions"><button data-action="new">New session</button><button class="secondary" data-action="import">Import progress</button>${list.length?'<button class="quiet" data-action="backup-all">Export all as backup</button>':''}</div>${list.length?list.map(row=>`<div class="session-row"><strong>${h(row.session?.teamAlias||'Unreadable session')}</strong><p class="caption">${row.error?h(row.error):`Stage ${row.session.currentStage} · App ${h(row.session.appVersion)} · ${h(row.session.updatedAt)}`}</p><div class="actions">${row.session?`<button class="secondary" data-resume="${h(row.id)}">Resume</button><button class="quiet" data-duplicate="${h(row.id)}">Duplicate</button>`:`<button class="quiet" data-recover="${h(row.id)}">Download raw recovery file</button>`}<button class="quiet" data-delete="${h(row.id)}">Delete</button></div></div>`).join(''):'<p style="margin-top:25px">No Road Trip sessions are saved on this device yet.</p>'}${list.length?'<div class="actions"><button class="danger" data-action="delete-all">Clear all Road Trip sessions</button></div>':''}<p class="caption">Downloaded files are separate from browser storage. An export is the portable copy for another device.</p>`)}
function makeCopy(source){const copy=C.clone(source);copy.duplicateOf=source.sessionId;copy.sessionId=C.id();copy.teamAlias=(source.teamAlias+' — copy').slice(0,64);copy.localRevision=0;copy.updatedAt=C.now();return copy}
function useSession(candidate){s=candidate;errors=[];notice='';conflict=false;saveError='';saveText=store.available?'Loaded saved work':'Device storage unavailable';closeModal();render(true)}
function newWork(){if(s){capture();save()}const fresh=C.newSession();useSession(fresh);save();render(true)}
function duplicate(source){const copy=makeCopy(source);if(store.available)store.save(copy);useSession(copy);notice='A separate copy is ready. Earlier history is retained and the original session is unchanged.';render(true)}
function deleteDialog(ids){pendingDelete=ids;const rows=ids.map(id=>{try{return {id,sess:store.read(id)}}catch{return {id,sess:null}}});openModal(ids.length===1?'Delete this session?':'Clear all Road Trip sessions?',`<div class="notice warning"><strong>${ids.length} session${ids.length===1?'':'s'} selected</strong><p>${rows.map(r=>h(r.sess?.teamAlias||r.id)).join('<br>')}</p></div><p>This removes the selected answers, attempts, help history, snapshots, overrides and reviews from this browser. Other apps and downloaded files are unaffected. Recovery requires an exported backup.</p><p class="caption">Export backup requests a download. Check that the file exists before confirming deletion. You may cancel at any time.</p><div class="actions"><button class="secondary" data-action="close">Cancel</button><button class="quiet" data-action="backup-selected">Export backup</button><button class="danger" data-action="confirm-delete">Delete ${ids.length} session${ids.length===1?'':'s'}</button></div>`)}
function backupIds(ids){let sessions=[],bad=[];for(const id of ids){try{const p=store.read(id);if(p)sessions.push(p)}catch{bad.push(id)}}if(bad.length){openModal('Backup needs recovery',`<p>${bad.length} unreadable session(s) cannot enter a validated backup bundle. Download their raw recovery files from Saved work. No records were removed.</p><div class="actions"><button class="secondary" data-action="sessions">Return to Saved work</button></div>`);return false}download('RoadTrip-backup-'+C.now().slice(0,10)+'.json',bundle(sessions));return true}
async function readImport(file){if(!file)return;try{if(file.size>20*1024*1024)throw Error('Choose a file no larger than 20 MiB.');pendingImport=C.parseImport(await file.text());const ids=store.ids(),collisions=pendingImport.filter(p=>ids.includes(p.sessionId));pendingReplace=false;openModal('Review import',`<p>${pendingImport.length} session(s) validated. Existing progress has not changed.</p>${pendingImport.map(p=>`<div class="session-row"><strong>${h(p.teamAlias||'Untitled team')}</strong><p class="caption">Stage ${p.currentStage} · App ${h(p.appVersion)} · Content ${h(p.contentVersion)}${ids.includes(p.sessionId)?' · Identity matches an existing session':''}</p></div>`).join('')}<p>Imported answers are checked against current mathematics. Reported history is labeled imported and does not certify independent work.</p><div class="actions"><button class="secondary" data-action="close">Cancel</button><button data-action="import-copy">Import as new copies</button>${collisions.length?'<button class="quiet" data-action="replace-preview">Replace matching sessions…</button>':''}</div>`)}catch(e){openModal('Import was not applied',`<p>${h(e.message)}</p><p>Your current and saved work have not changed.</p><button class="secondary" data-action="import">Choose another file</button>`)}}
function commitImport(replace){const incoming=pendingImport.map(p=>replace?C.clone(p):makeCopy(p));for(const p of incoming){p.imported=true;if(replace){let old;try{old=store.read(p.sessionId)}catch{}p.localRevision=(old?.localRevision||0)+1;p.updatedAt=C.now()}}store.saveMany(incoming);pendingImport=null;useSession(incoming[0]);notice=`Imported ${incoming.length} session(s). History is marked imported; current mathematical evidence was revalidated.`;render(true)}
function expected(def){if(def.kind==='expression')return `${def.m.str()}d ${def.b.cmp(0)<0?'−':'+'} ${def.b.cmp(0)<0?def.b.neg().str():def.b.str()}`;if(def.kind==='numeric')return def.expected.str()+(def.unit?' '+def.unit:'');if(def.kind==='inequality'){const m=C.scenario(s);return `${m.m.str()}d + (${m.b.str()}) ≤ 1800`};if(def.kind==='text')return 'Teacher review of reasoning';if(def.kind==='notRequired')return 'Not required for current state';return Array.isArray(def.expected)?def.expected.join(' / '):def.expected}
function teacherModal(){openModal('Teacher desk',`<p>This local classroom control shows solutions and review tools. It is not a password, secure concealment, or a tamper-proof gradebook.</p><button class="secondary" data-action="toggle-teacher">${teacher?'Leave':'Enter'} teacher mode</button>${teacher?`<div class="actions"><button class="quiet" data-action="teacher-print">Print teacher reference</button><button class="quiet" data-action="slips">Print transfer slips</button><button class="quiet" data-action="diagnostics">Export local diagnostics</button></div>${s?`<section class="panel"><h3>Record a review</h3><label class="field">Reviewer alias<input id="reviewer" maxlength="64" autocomplete="off"></label><label class="field">Evidence<select id="review-key"><option value="reason">Recommendation reasoning</option><option value="reserveStatement">Reserve statement</option><option value="routeReviewed">Research source truth / conversion</option><option value="transferModeA">Learner A transfer</option><option value="transferModeB">Learner B transfer</option></select></label><label class="field">Review status<select id="review-status"><option value="pending">Pending</option><option value="verified">Verified by teacher</option><option value="revise">Needs revision / follow-up</option></select></label><label class="field">Review note<input id="review-note" maxlength="280"></label><div class="actions"><button data-action="record-review">Record review</button></div></section><section class="panel"><h3>Explicit checkpoint bypass</h3><p>A bypass is logged with reviewer, reason and time. Active bypasses produce a provisional outcome.</p><label class="field">Checkpoint<select id="bypass-group">${Object.keys(C.groups).map(g=>`<option value="${g}">${g} · ${C.labels[g]}</option>`).join('')}</select></label><label class="field">Reason<input id="bypass-reason" maxlength="280"></label><div class="actions"><button class="secondary" data-action="bypass">Record bypass</button></div></section><details><summary>Active scenario solution key</summary>${Object.entries(C.groups).map(([g,ks])=>`<h3>${g} · ${C.labels[g]}</h3>${ks.map(k=>`<p class="caption"><strong>${h(C.definitions(s)[k].label)}:</strong> ${h(expected(C.definitions(s)[k]))}</p>`).join('')}`).join('')}</details>`:'<p>Start or resume a session to review its evidence.</p>'}`:''}`)}
function recordReview(key,status,reviewer,note=''){if(!reviewer.trim())throw Error('Enter a reviewer alias.');if(key==='routeReviewed'){C.setInput(s,'routeReviewed',status);key='routeReviewed'}s.reviews.push({key,status,reviewer:reviewer.trim(),note,at:C.now(),fingerprint:C.fingerprint(s,key),response:s.inputs[key]||''});save()}
function header(page,title){return `<div class="report-header"><span>A WILLIAM MCADA PRODUCT · Road Trip Planner</span><span>${h(s?.teamAlias||'Teacher reference')} · ${h(C.now().slice(0,10))} · App 0.1.0 / Content 1.0.0 · ${title} ${page}</span></div>`}
function studentReport(){const m=C.scenario(s),o=C.outcome(s),line=k=>`${value(k)} <small>(${h(statusName[C.state(s,k)])})</small>`,base=s.eventBaseline,event=s.eventEvidence,rows=[['Vehicle',m.selected.vehicle[1],money(m.r)+'/group/day','7 days'],['Lodging',m.selected.hotel[1],money(m.h)+'/group/night','6 nights'],['Food',m.selected.food[1],money(m.f)+'/person/day','3 people × 7 days'],['Activities',m.selected.activities[1],money(m.a)+'/group/day','7 days'],['One-off','Booking + luggage + supplies','$40 + $80 + $80','Once'],['Fuel',h(txt('routeDistance'))+' km','$1.60/L · 12 km/L','Once for route']];return `<section class="report-page">${header(1,'Proposal page')}<p class="eyebrow">Your seven-day client proposal</p><h2>${h(s.teamAlias||'Untitled team')}</h2><p><strong>${h(o.title)}</strong>${s.imported?' · Imported evidence':''}</p><p>Three travelers · Seven days · $1,800 budget · Whole-day model domain 1–14.</p><p>Priorities: comfortable lodging and full activities. Planner ${h(txt('planner'))}; Checker ${txt('planner')==='A'?'B':'A'}.</p><h3>Route and source</h3><p>Total route: ${value('routeDistance')} km. Fuel efficiency: 12 km/L. Fuel price: $1.60/L.</p><p>Source: ${h(txt('routeMode')==='provided'?'Harbor City–Lakeview authored classroom route':txt('sourceTitle'))}. ${txt('routeMode')==='researched'?`Recorded distance: ${value('originalDistance')} ${value('originalUnit')}; type: ${value('routeType')}; segments: ${value('segments')}. Accessed: ${value('accessDate')}. Source review: ${h(txt('routeReviewed'))}.`:''}</p>${txt('routeMode')==='researched'?`<p>Provider / link: ${value('sourceLink')}</p>`:''}<h3>Selected itinerary and prices</h3><table><thead><tr><th>Cost</th><th>Choice</th><th>Rate</th><th>Basis</th></tr></thead><tbody>${rows.map(r=>'<tr>'+r.map(c=>'<td>'+c+'</td>').join('')+'</tr>').join('')}</tbody></table><p>Fuel calculation entered: ${line('liters')} L; fuel subtotal entered: ${line('fuelCost')} USD. Food for the group/day: ${line('partyFood')} USD.</p><p>Hotel rule entered: <span class="math">${value('hotelExpression')}</span>. Nights entered: ${line('nights')}.</p><p>Active quote: ${s.eventApplied?'base hotel rate plus $20/night, applied once':'original catalog'}. Client fit: ${m.U}/100 (design preference, not an academic grade).</p><h3>Review status</h3><p>${reviewSummary()}</p><p class="caption">This proposal records submitted work. Unchecked or stale answers remain labeled; a printed draft is not a verified completion.</p></section>
<section class="report-page">${header(2,'Proposal page')}<h2>Show how the numbers work</h2><p>Student rule: <span class="math">C(d) = ${value('expression')}</span> · ${h(statusName[C.state(s,'expression')])}</p><p>m = ${line('slope')} USD/day · b = ${line('constant')} USD.</p><p class="caption">Selected interpretations: m — ${h((opts.slopeMeaning.find(a=>a[0]===txt('slopeMeaning'))||[])[1]||'not entered')}; b — ${h((opts.constantMeaning.find(a=>a[0]===txt('constantMeaning'))||[])[1]||'not entered')}. Domain: ${h((opts.domain.find(a=>a[0]===txt('domain'))||[])[1]||'not entered')}.</p><table><tr><th>Days</th>${[1,3,5,7].map(d=>'<th>'+d+'</th>').join('')}</tr><tr><th>Table cost (USD)</th>${[1,3,5,7].map(d=>'<td>'+line('table'+d)+'</td>').join('')}</tr><tr><th>Plotted pair</th>${[1,3,5,7].map(d=>'<td>('+value('x'+d)+', '+value('y'+d)+')</td>').join('')}</tr></table>${graph()}<p class="caption">Graph records entered points and budget height ${value('budgetLine')} USD. Checked model line is shown only after current plotting checks. Day zero is outside the trip domain. One-day rise entered: ${line('rise')} USD/day.</p><h3>Affordability</h3><p>Inequality: <span class="math">${value('inequality')}</span> · ${h(statusName[C.state(s,'inequality')])}</p><p>Continuous upper bound: <span class="math">${rational(txt('bound'))}</span> · ${h(statusName[C.state(s,'bound')])}; longest whole-day trip entered: ${line('maxDays')}.</p><p>Cost at maximum entered: ${line('costAtMax')} USD. ${C.definitions(s).nextDayCost.kind==='notRequired'?'Next-day check is outside the supported domain or no day is affordable.':'Next whole day entered: '+line('nextDayCost')+' USD.'}</p></section>
<section class="report-page">${header(3,'Proposal page')}<h2>A changed quote. A considered decision.</h2><div class="compare">${[['Before',base],['Hotel event',event],['Final active',null]].map(([title,snap])=>`<div><small>${title}</small><strong>${snap?money(snap.scenario.total):title==='Final active'&&C.state(s,'total')==='verified'?money(m.total):'Not checked'}</strong><span class="caption">${snap?`Historical snapshot · m ${h(snap.scenario.m)}, b ${h(snap.scenario.b)}`:title==='Final active'?`Active revision ${s.scenarioRevision}`:'No snapshot'}</span></div>`).join('')}</div><p class="caption">Historical amounts are the frozen scenario quantities, separate from current student responses. ${!s.eventEvidence?'The mandatory hotel comparison has not been completed.':''}</p><p>Hotel-event changes entered: m ${line('deltaSlope')} USD/day; b ${line('deltaConstant')} USD; seven-day cost ${line('deltaTotal')} USD.</p><h3>Recommendation</h3><p>Decision: ${h(txt('recommendation')==='recommend'?'Recommend this plan':txt('recommendation')==='revise'?'Recommend a revision':'Not entered')}. Evidence: ${value('evidenceType')} = ${line('evidenceValue')}.</p><p>${value('reason')}</p><p>Seven-day total: ${line('total')} USD. Reserve: ${line('reserve')} USD. Spending: ${line('percent')}%.</p><p>Reserve allocation / revision: ${C.definitions(s).reserveStatement.kind==='notRequired'?'No extra statement required for the 0–5% reserve band.':value('reserveStatement')}</p><div class="ending">${A.postcard(o.code)}<div><h3>${h(o.title)}</h3><p>${o.code==='draft'?'Finish missing or stale checks.':`${h(m.selected.hotel[1])} · ${h(m.selected.food[1])} · ${h(m.selected.activities[1])}. ${money(m.total)} total; ${money(m.reserve)} left; ${m.U}/100 client fit.`}</p></div></div><p>Review status: ${reviewSummary()}</p><p class="caption">Complete response first recorded: ${h(s.completedAt||'not yet complete')}. ${s.teacherOverrides.length} historical bypass(es); ${C.baseKeys.concat(C.groups.C08,C.groups.C09).filter(k=>C.state(s,k)==='overridden').length} active bypassed fields. A bypass never becomes ordinary verified work.</p></section>
<section class="report-page">${header(4,'Proposal page')}<h2>Individual work and learning evidence</h2>${['A','B'].map(a=>`<h3>Learner ${a}</h3><p>${a==='A'?'$160/day plus $240 once; find four-day cost.':'$145/day plus $310 once; find six-day cost.'} Mode: ${value('transferMode'+a)}.</p><p>${txt('transferMode'+a)==='digital'?`Rule entered: ${line('transferExpression'+a)}; total entered: ${line('transferTotal'+a)} USD.`:`Teacher-recorded evidence: ${C.reviewStatus(s,'transferMode'+a)}. No digital response is inferred.`}</p>`).join('')}<h3>First checks and corrections</h3><table><thead><tr><th>Checkpoint</th><th>First checked responses</th><th>Active final state</th><th>Attempts / help</th></tr></thead><tbody>${Object.entries(C.groups).map(([g,ks])=>{const attempts=s.attempts.filter(a=>a.checkpointId==='RT-'+g),first=ks.map(k=>attempts.find(a=>a.key===k)).filter(Boolean);return `<tr><td>${g} ${C.labels[g]}</td><td>${first.length?first.filter(a=>a.passed).length+' / '+first.length+' correct at first check':'Not checked'}</td><td>${C.groupOK(s,g)?ks.some(k=>C.state(s,k)==='overridden')?'Provisional bypass':'Current':'Incomplete / needs recheck'}</td><td>${attempts.length} / ${s.support.filter(a=>a.checkpointId==='RT-'+g).length}</td></tr>`}).join('')}</tbody></table><p class="caption">Counts are field submissions, not a mastery score. First and final raw responses, timestamps, scenario revisions, source snapshots, reviews and override reasons are retained in the exported JSON. Correct siblings are not resubmitted automatically. ${s.imported?'This history was imported and is not independently certified.':''}</p><p>Teacher reviews: ${reviewSummary()}</p><p class="caption">Sessions use aliases. This local activity does not securely conceal solutions or provide tamper-proof assessment. Teacher observation and individual follow-up remain separate.</p></section>`}
function teacherReport(){return `<section class="report-page">${header(1,'Teacher page')}<h2>Road Trip Planner — teacher reference</h2><p>Three lessons of about 45 minutes; pairs rotate Planner/Checker after stages 3 and 6. Prior knowledge: rational arithmetic, expressions, graph coordinates and simple inequalities. Advanced Grade 5 / Saxon 8/7 context; use teacher judgment.</p><h3>Canonical route and worked key</h3><p>3 travelers; 7 days / 6 nights; 900 km; 12 km/L; $1.60/L; one-off $200; budget $1,800. Fuel: 75 L, $120. Classification: one-off and fuel once; vehicle, food, activities daily; hotel nightly.</p><p class="math">C(d) = 200 + 120 + rd + h(d − 1) + 3fd + ad<br>m = r + h + 3f + a; b = 200 + 120 − h</p><table><tr><th>Scenario</th><th>m / b</th><th>C(1), C(3), C(5), C(7)</th><th>Reserve / spent</th><th>Bound / whole days</th></tr><tr><td>Base 40/90/20/30</td><td>220 / 230</td><td>450, 890, 1330, 1770</td><td>$30 / 98.33%</td><td>${rational('157/22')} / 7</td></tr><tr><td>Hotel 110</td><td>240 / 210</td><td>450, 930, 1410, 1890</td><td>−$90 / 105%</td><td>${rational('53/8')} / 6</td></tr><tr><td>Food revision 15</td><td>225 / 210</td><td>435, 885, 1335, 1785</td><td>$15 / 99.17%</td><td>${rational('106/15')} / 7</td></tr></table><p>Base C(8) = $1,990; revised C(8) = $2,010. Hotel changes: +20 to m, −20 to b, +120 total over six nights. Every hotel category receives the $20/night rise exactly once. Freeze and verify this event before permitting another choice revision.</p><p>Equivalent rules such as 220d + 230 and 200 + 120 + 40d + 90(d − 1) + 60d + 30d pass. A right seven-day total does not prove a full model. The intercept is an adjusted constant, not literal spending for a zero-day trip. Domain: whole days 1–14.</p><h3>Transfer keys — teacher only</h3><p>A: T(d) = 160d + 240, T(4) = $880. B: T(d) = 145d + 310, T(6) = $1,180. Show one learner at a time. Paper/oral submissions require a reviewer record and retain pending/verified/revise status.</p><h3>Review guidance</h3><p>Review reasoning quality, source truth, and oral/paper transfer separately from automatic arithmetic. Negative reserve and spending above 100% may be correct. Do not mark poor design as an arithmetic error. Any active bypass makes completion provisional. An independent correct recheck retires the active bypass while keeping history.</p><p class="caption">This reference contains keys; print separately from student proposals. No client-side teacher mode can securely conceal answers.</p></section><section class="report-page">${header(2,'Teacher page')}<h2>Choices, outcomes and classroom use</h2><table><tr><th>Category</th><th>Prices (USD)</th><th>Client fit points</th></tr>${Object.entries(C.CAT).map(([k,rows])=>`<tr><td>${h(k)}</td><td>${rows.map(v=>h(v[1])+': '+v[2]).join('<br>')}${k==='hotel'?'<br>All quotes rise by $20/night.':''}</td><td>${rows.map(v=>v[3]).join(' / ')}</td></tr>`).join('')}</table><h3>Outcome precedence</h3><p>Missing/stale work or no recorded hotel comparison: Draft. Active bypass: Provisional. Current plan over budget or fit &lt;65: Revision requested. Within budget and fit 65–84: Trip approved. Within budget and fit ≥85: Client delighted. Pending prose/research/transfer review is always separate.</p><table><tr><th>Final event-price example</th><th>Cost / fit</th><th>Outcome</th></tr><tr><td>Standard car, standard hotel, full food, full activities</td><td>$1,890 / 100</td><td>Revision requested</td></tr><tr><td>Standard car, standard hotel, balanced food, full activities</td><td>$1,785 / 95</td><td>Client delighted</td></tr><tr><td>Basic car, basic hotel, simple food, full activities</td><td>$1,430 / 70</td><td>Trip approved; reserve statement needed</td></tr><tr><td>Basic car, basic hotel, simple food, light activities</td><td>$1,290 / 50</td><td>Revision requested despite correct affordable math</td></tr><tr><td>Basic car, standard hotel, balanced food, full activities</td><td>$1,715 / 95</td><td>Client delighted; a large justified reserve is allowed</td></tr></table><h3>Common misconceptions</h3><p>Fuel follows the route, not the number of days. Food price is per person. Seven days includes six nights. Expand h(d − 1) before collecting b. Points are (days, cost); budget is horizontal. Round fuel only at the subtotal and percentage to 0.01%; keep exact fractions for recurring bounds.</p><h3>Saving and recovery</h3><p>Use an alias. Export after each lesson and before moving devices. Import previews all records; copies are the default. Replacing or deleting requires a named confirmation and backup option. If device storage fails, keep the page open and export. A second tab offers reload or save as copy.</p><p>Calculator allowed for arithmetic; students must construct the model, inequality, graph and interpretation. Help examples use different numbers. Paper slips contain no keys. No timer, accounts, cloud synchronization, telemetry, or live map API.</p><p class="caption">Desktop offline and emulated-device verification do not replace a physical Safari iPad and school-network check.</p></section>`}
function slipsReport(){return ['A','B'].map((a,i)=>`<section class="report-page">${header(i+1,'Transfer slip')}<h2>Individual transfer · Learner ${a}</h2><p>Team alias: ____________________ &nbsp; Date: ____________________</p><div class="slip"><p>${a==='A'?'A different trip costs $160 each day and $240 once. Write T(d). Find the cost for four days.':'Another trip costs $145 each day and $310 once. Write T(d). Find the cost for six days.'}</p><p>My rule T(d):</p><div class="line"></div><p>My trip total (USD; calculator allowed):</p><div class="line"></div><p>How I know:</p><div class="line"></div></div><p>Work independently. Teacher review: pending / verified / follow-up.<br>Reviewer alias: ____________________</p><p class="caption">This slip contains no answer key. Keep learner responses separate during the task.</p></section>`).join('')}
function reportModal(type){if(s){capture();save()}const body=type==='student'?studentReport():type==='teacher'?teacherReport():slipsReport();$('#print-root').innerHTML=body;openModal(type==='student'?'Proposal preview':type==='teacher'?'Teacher reference':'Separate transfer slips',`<p>Use A4 or Letter, portrait, 100% scale. Disable browser headers/footers. ${type==='student'?'Four student pages; checked and pending work are labeled.':type==='teacher'?'Two pages, with teacher-only answers.':'Two pages, one learner per page; no keys.'}</p><div class="actions"><button data-action="print">Print / save PDF</button><button class="secondary" data-action="close">Close preview</button></div><div class="report-preview">${body}</div>`)}
function diagnose(){download('RoadTrip-diagnostics.json',{appVersion:C.VERSION,contentVersion:C.CONTENT,at:C.now(),storageAvailable:store.available,saveState:saveText,conflict,stage:s?.currentStage||0,eventApplied:s?.eventApplied||false,checkpoints:s?Object.fromEntries(Object.entries(C.groups).map(([g,ks])=>[g,Object.fromEntries(ks.map(k=>[k,C.state(s,k)]))])):{},validationErrorFields:errors.map(e=>e.key)});}
function complete(){capture();if(!checkKeys(C.groups.C09))return;const o=C.outcome(s);if(o.code!=='draft'&&!s.completedAt)s.completedAt=C.now();save();render(true)}
function reportError(e){openModal('Please check',`<p>${h(e.message||e)}</p>${s?'<button class="secondary" data-action="export">Export current progress</button>':''}`)}
document.addEventListener('click',async event=>{const target=event.target.closest('button,a,[data-plot]');if(!target)return;try{
 if(target.dataset.errorLink){event.preventDefault();let el=$('#f-'+target.dataset.errorLink)||$('#team-alias');el?.closest('details')?.setAttribute('open','');el?.focus();return}
 if(target.dataset.help)return showHelp(target.dataset.help);
 if(target.dataset.stage){capture();let n=Number(target.dataset.stage);if(n>s.maxStage||!C.canStage(s,n)){notice=n>s.maxStage?'Finish the current stage to unlock this part of the journey.':'Earlier calculations need rechecking. Return to the first affected stage.';render();return}s.currentStage=n;errors=[];notice='';save();render(true);return}
 if(target.dataset.check)return checkKeys(C.groups[target.dataset.check]);
 if(target.dataset.learner){capture();learner=target.dataset.learner;save();render();return}
 if(target.dataset.transfer)return checkKeys(['transferMode'+target.dataset.transfer,'transferExpression'+target.dataset.transfer,'transferTotal'+target.dataset.transfer]);
 if(target.dataset.recordTransfer){const a=target.dataset.recordTransfer;return openModal('Record learner '+a+' submission',`<p>Mode: ${h(txt('transferMode'+a))}. Record that the work was actually submitted. Review is initially pending.</p><label class="field">Reviewer alias<input id="submission-reviewer" maxlength="64"></label><div class="actions"><button data-submit-transfer="${a}">Record submitted work</button></div>`)}
 if(target.dataset.submitTransfer){const a=target.dataset.submitTransfer;recordReview('transferMode'+a,'pending',$('#submission-reviewer').value);C.check(s,['transferMode'+a]);save();closeModal();render();return}
 if(target.dataset.resume){if(s){capture();save()}const next=store.read(target.dataset.resume);if(next)useSession(next);return}
 if(target.dataset.duplicate)return duplicate(store.read(target.dataset.duplicate));
 if(target.dataset.delete)return deleteDialog([target.dataset.delete]);
 if(target.dataset.recover)return download('RoadTrip-recovery-'+target.dataset.recover+'.json',storage.getItem(C.PREFIX+'session:'+target.dataset.recover));
 if(target.dataset.plot){const b=target.getBoundingClientRect(),x=(event.clientX-b.left)/b.width*720,y=(event.clientY-b.top)/b.height*370,days=Math.max(1,Math.min(14,Math.round((x-62)/(720-62-22)*14))),cost=Math.max(0,(370-53-y)/(370-22-53)*Number(target.dataset.upper));C.setInput(s,'x'+plotPoint,String(days));C.setInput(s,'y'+plotPoint,cost.toFixed(2));save();render();return}
 const action=target.dataset.action;if(!action)return;
 switch(action){case 'close':closeModal();break;case 'new':newWork();break;case 'save':capture();save();render();break;case 'sessions':if(s){capture();save()}sessionsModal();break;case 'export':exportSession();break;case 'import':$('#import-file').value='';$('#import-file').click();break;case 'next':next();break;case 'back':capture();s.currentStage=Math.max(1,s.currentStage-1);errors=[];notice='';save();render(true);break;case 'swap':capture();C.setInput(s,'planner',txt('planner')==='A'?'B':'A');notice='Roles swapped. Planner '+txt('planner')+' enters; the other learner checks.';save();render();break;case 'ratings':openModal('Client priorities',ratings());break;case 'proposal':reportModal('student');break;case 'teacher':teacherModal();break;case 'toggle-teacher':teacher=!teacher;render();teacherModal();break;case 'teacher-print':if(teacher)reportModal('teacher');break;case 'slips':reportModal('slips');break;case 'print':window.print();break;case 'diagnostics':diagnose();break;case 'finish':complete();break;
 case 'apply-event':capture();C.applyEvent(s);errors=[];notice='The original plan is frozen. Update the hotel term, model and affected results.';save();render(true);break;
 case 'record-event':if(checkKeys(C.stageKeys(7,s))){if(!s.eventEvidence)C.recordEvent(s);notice='Hotel comparison recorded. You can revise choices or keep this analyzed plan.';save();render()}break;
 case 'revise':capture();if(s.eventApplied&&!s.eventEvidence)throw Error('Record the required hotel comparison before changing choices.');s.currentStage=3;errors=[];notice='Choose a revision, then recheck the affected calculations. Earlier work is retained.';save();render(true);break;
 case 'keep-plan':if(!C.baseKeys.every(k=>C.valid(s,k)))throw Error('Recheck the active plan before keeping it.');notice='This analyzed plan is retained. Continue to the client presentation.';render();break;
 case 'duplicate-active':capture();save();duplicate(s);break;case 'delete-all':deleteDialog(store.ids());break;case 'backup-all':backupIds(store.ids());break;case 'backup-selected':backupIds(pendingDelete);break;
 case 'confirm-delete':{const ids=[...pendingDelete];store.remove(ids);if(s&&ids.includes(s.sessionId)){s=null;saveError='';saveText='No active session'}pendingDelete=[];closeModal();render(true);sessionsModal();break}
 case 'import-copy':commitImport(false);break;
 case 'replace-preview':{const matching=pendingImport.filter(p=>store.ids().includes(p.sessionId));pendingReplace=true;openModal('Replace matching saved work?',`<p>This will replace ${matching.length} named session(s), including their current answers, attempts and reviews:</p><p>${matching.map(p=>h(p.teamAlias||p.sessionId)).join('<br>')}</p><p>Unmatched sessions will be added. Download a backup and verify it exists before replacing.</p><div class="actions"><button class="secondary" data-action="close">Cancel</button><button class="quiet" data-action="backup-replace">Export existing backup</button><button class="danger" data-action="confirm-replace">Confirm replacement</button></div>`);break}
 case 'backup-replace':backupIds(pendingImport.filter(p=>store.ids().includes(p.sessionId)).map(p=>p.sessionId));break;case 'confirm-replace':if(pendingReplace)commitImport(true);break;
 case 'reload-conflict':{const saved=store.read(s.sessionId);if(saved)useSession(saved);break}
 case 'copy-conflict':{const copy=makeCopy(s);store.save(copy);useSession(copy);notice='Your in-memory work was saved as a separate copy.';render();break}
 case 'record-review':recordReview($('#review-key').value,$('#review-status').value,$('#reviewer').value,$('#review-note').value);closeModal();notice='Teacher review recorded separately from arithmetic.';render();break;
 case 'bypass':C.bypass(s,$('#bypass-group').value,$('#reviewer').value,$('#bypass-reason').value);save();closeModal();notice='Teacher bypass logged. Active bypassed completion is provisional.';render();break;
 case 'open-source':{const u=new URL(txt('sourceLink'));if(!['http:','https:'].includes(u.protocol))throw Error('Only http or https source links can be opened.');window.open(u.href,'_blank','noopener,noreferrer');break}
 }
 }catch(e){reportError(e)}});
document.addEventListener('change',event=>{const el=event.target;try{if(el.id==='import-file'){readImport(el.files[0]);return}if(el.id==='plot-point'){plotPoint=Number(el.value);return}if(!s)return;if(el.id==='team-alias'){s.teamAlias=el.value;save();return}const key=el.dataset.field;if(!key)return;C.setInput(s,key,el.value);errors=errors.filter(e=>e.key!==key);if(key==='routeMode'){if(el.value==='provided'){for(const [k,v]of Object.entries({sourceTitle:'Harbor City–Lakeview classroom route',routeDistance:'900',originalDistance:'900',originalUnit:'km',routeType:'roundTrip',routeReviewed:'provided'}))C.setInput(s,k,v)}else C.setInput(s,'routeReviewed','pending')}if(['sourceTitle','sourceLink','accessDate','originalDistance','originalUnit','segments','routeType','routeDistance'].includes(key)&&txt('routeMode')==='researched')C.setInput(s,'routeReviewed','pending');save();if(el.tagName==='SELECT'||el.type==='radio'){render();$('#f-'+key)?.focus()}}catch(e){reportError(e)}});
$('#modal').addEventListener('click',event=>{if(event.target===$('#modal')){const r=event.target.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)closeModal()}});
$('#modal').addEventListener('close',()=>{modalReturn?.isConnected&&modalReturn.focus()});
window.addEventListener('storage',event=>{if(!s||event.key!==C.PREFIX+'session:'+s.sessionId||!event.newValue)return;try{const p=JSON.parse(event.newValue);if(p.localRevision>s.localRevision){conflict=true;saveError='A newer copy exists in another tab. Reload it or save your current work as a new copy.';saveText='Conflict — current work retained';updateSave()}}catch{}});
window.addEventListener('beforeunload',()=>{if(s&&!conflict){try{capture();save()}catch{}}});
if(!store.available)saveError='Device storage is unavailable. Work can continue in memory; export progress before leaving.';
render();
})();
